changeSet.sql:
UPDATE pacchetti SET numero_lezioni = 1 WHERE nome LIKE '%Prima Lezione%';
UPDATE pacchetti SET numero_lezioni = 4 WHERE nome LIKE '%4 Lezioni%';
UPDATE pacchetti SET numero_lezioni = 8 WHERE nome LIKE '%8 Lezioni%';
UPDATE pacchetti SET numero_lezioni = 10 WHERE nome LIKE '%10 Lezioni%';

UPDATE pacchetti
SET numero_lezioni = CAST(REGEXP_SUBSTR(nome, '[0-9]+') AS UNSIGNED)
WHERE numero_lezioni IS NULL AND nome REGEXP '[0-9]+';
